478: func (ca *certificateAuthorityImpl) issuePrecertificateInner(ctx context.Context, issueReq *capb.IssueCertificateRequest, serialBigInt *big.Int, validity validity) ([]byte, *issuance.Issuer, error) {
479: 	// The CA must check if it is capable of issuing for the given
480: 	// certificate profile name. The name is checked here instead of the
481: 	// hash because the RA is unaware of what certificate profiles exist.
482: 	if issueReq.CertProfileName == "" {
483: 		issueReq.CertProfileName = DefaultCertProfileName
484: 	}
485: 	profileHashBytes, ok := ca.certProfiles.hashByName[issueReq.CertProfileName]
486: 	if !ok {
487: 		return nil, nil, fmt.Errorf("the CA is not capable of using a profile named %s", issueReq.CertProfileName)
488: 	}
489: 
490: 	csr, err := x509.ParseCertificateRequest(issueReq.Csr)
491: 	if err != nil {
492: 		return nil, nil, err
493: 	}
494: 
495: 	err = csrlib.VerifyCSR(ctx, csr, ca.maxNames, &ca.keyPolicy, ca.pa)
496: 	if err != nil {
497: 		ca.log.AuditErr(err.Error())
498: 		// VerifyCSR returns berror instances that can be passed through as-is
499: 		// without wrapping.
500: 		return nil, nil, err
501: 	}
502: 
503: 	var issuer *issuance.Issuer
504: 	if issueReq.IssuerNameID == 0 {
505: 		// Use the issuer which corresponds to the algorithm of the public key
506: 		// contained in the CSR, unless we have an allowlist of registration IDs
507: 		// for ECDSA, in which case switch all not-allowed accounts to RSA issuance.
508: 		alg := csr.PublicKeyAlgorithm
509: 		if alg == x509.ECDSA && !features.Get().ECDSAForAll && ca.ecdsaAllowList != nil && !ca.ecdsaAllowList.permitted(issueReq.RegistrationID) {
510: 			alg = x509.RSA
511: 		}
512: 		issuer, ok = ca.issuers.byAlg[alg]
513: 		if !ok {
514: 			return nil, nil, berrors.InternalServerError("no issuer found for public key algorithm %s", csr.PublicKeyAlgorithm)
515: 		}
516: 	} else {
517: 		issuer, ok = ca.issuers.byNameID[issuance.NameID(issueReq.IssuerNameID)]
518: 		if !ok {
519: 			return nil, nil, berrors.InternalServerError("no issuer found for IssuerNameID %d", issueReq.IssuerNameID)
520: 		}
521: 	}
522: 
523: 	if issuer.Cert.NotAfter.Before(validity.NotAfter) {
524: 		err = berrors.InternalServerError("cannot issue a certificate that expires after the issuer certificate")
525: 		ca.log.AuditErr(err.Error())
526: 		return nil, nil, err
527: 	}
528: 
529: 	subjectKeyId, err := generateSKID(csr.PublicKey)
530: 	if err != nil {
531: 		return nil, nil, fmt.Errorf("computing subject key ID: %w", err)
532: 	}
533: 
534: 	serialHex := core.SerialToString(serialBigInt)
535: 
536: 	ca.log.AuditInfof("Signing precert: serial=[%s] regID=[%d] names=[%s] csr=[%s]",
537: 		serialHex, issueReq.RegistrationID, strings.Join(csr.DNSNames, ", "), hex.EncodeToString(csr.Raw))
538: 
539: 	names := csrlib.NamesFromCSR(csr)
540: 	req := &issuance.IssuanceRequest{
541: 		PublicKey:         csr.PublicKey,
542: 		SubjectKeyId:      subjectKeyId,
543: 		Serial:            serialBigInt.Bytes(),
544: 		DNSNames:          names.SANs,
545: 		CommonName:        names.CN,
546: 		IncludeCTPoison:   true,
547: 		IncludeMustStaple: issuance.ContainsMustStaple(csr.Extensions),
548: 		NotBefore:         validity.NotBefore,
549: 		NotAfter:          validity.NotAfter,
550: 	}
