552: 	// The certificate profile hash is checked here instead of the name because
553: 	// the hash is over the entire contents of a *ProfileConfig which includes
554: 	// the name giving more assurance that the certificate profile has remained
555: 	// unchanged during the roundtrip from a CA, to the RA, then back to a CA.
556: 	lintCertBytes, issuanceToken, err := issuer.Prepare(ca.certProfiles.profileByHash[profileHashBytes], req)
557: 	//certProfileCountLabels := prometheus.Labels{"purpose": string(precertType), "profile": issueReq.CertProfileName, "hash": hex.EncodeToString(profileHashBytes[:])}
558: 	if err != nil {
559: 		ca.log.AuditErrf("Preparing precert failed: serial=[%s] regID=[%d] names=[%s] certProfileName=[%s] certProfileHash=[%s] err=[%v]",
560: 			serialHex, issueReq.RegistrationID, strings.Join(csr.DNSNames, ", "), issueReq.CertProfileName, hex.EncodeToString(profileHashBytes[:]), err)
561: 		if errors.Is(err, linter.ErrLinting) {
562: 			ca.lintErrorCount.Inc()
563: 		}
564: 		return nil, nil, berrors.InternalServerError("failed to prepare precertificate signing: %s", err)
565: 	}
566: 
567: 	_, err = ca.sa.AddPrecertificate(context.Background(), &sapb.AddCertificateRequest{
568: 		Der:          lintCertBytes,
569: 		RegID:        issueReq.RegistrationID,
570: 		Issued:       timestamppb.New(ca.clk.Now()),
571: 		IssuerNameID: int64(issuer.NameID()),
572: 		OcspNotReady: true,
573: 	})
574: 	if err != nil {
575: 		return nil, nil, err
576: 	}
577: 
578: 	certDER, err := issuer.Issue(issuanceToken)
579: 	if err != nil {
580: 		ca.noteSignError(err)
581: 		ca.log.AuditErrf("Signing precert failed: serial=[%s] regID=[%d] names=[%s] certProfileName=[%s] certProfileHash=[%s] err=[%v]",
582: 			serialHex, issueReq.RegistrationID, strings.Join(csr.DNSNames, ", "), issueReq.CertProfileName, hex.EncodeToString(profileHashBytes[:]), err)
583: 		return nil, nil, berrors.InternalServerError("failed to sign precertificate: %s", err)
584: 	}
585: 
586: 	ca.signatureCount.With(prometheus.Labels{"purpose": string(precertType), "issuer": issuer.Name()}).Inc()
587: 	ca.log.AuditInfof("Signing precert success: serial=[%s] regID=[%d] names=[%s] precertificate=[%s] certProfileName=[%s] certProfileHash=[%s]",
588: 		serialHex, issueReq.RegistrationID, strings.Join(csr.DNSNames, ", "), hex.EncodeToString(certDER), issueReq.CertProfileName, hex.EncodeToString(profileHashBytes[:]))
589: 
590: 	return certDER, issuer, nil
591: }

