564: 		return nil, [32]byte{}, err
565: 	}
566: 
567: 	certDER, err := issuer.Issue(issuanceToken)
568: 	if err != nil {
569: 		ca.noteSignError(err)
570: 		ca.log.AuditErrf("Signing precert failed: serial=[%s] regID=[%d] names=[%s] certProfileName=[%s] certProfileHash=[%s] err=[%v]",
571: 			serialHex, issueReq.RegistrationID, strings.Join(csr.DNSNames, ", "), issueReq.CertProfileName, hex.EncodeToString(profileHashBytes[:]), err)
572: 		return nil, [32]byte{}, berrors.InternalServerError("failed to sign precertificate: %s", err)
573: 	}
574: 
575: 	ca.signatureCount.With(prometheus.Labels{"purpose": string(precertType), "issuer": issuer.Name()}).Inc()
576: 	ca.log.AuditInfof("Signing precert success: serial=[%s] regID=[%d] names=[%s] precertificate=[%s] certProfileName=[%s] certProfileHash=[%s]",
577: 		serialHex, issueReq.RegistrationID, strings.Join(csr.DNSNames, ", "), hex.EncodeToString(certDER), issueReq.CertProfileName, hex.EncodeToString(profileHashBytes[:]))
578: 
579: 	return certDER, profileHashBytes, nil
580: }
